def plan_vmss_rollout(model_image,upgrade_mode,instances):
    if upgrade_mode not in ("Manual","Automatic","Rolling"):raise ValueError("unsupported upgrade policy")
    if not isinstance(instances,list) or any(not isinstance(x,dict) or not x.get("instanceId") or not x.get("image") for x in instances):
        raise ValueError("instances require instanceId and image")
    stale=sorted(x["instanceId"] for x in instances if x["image"]!=model_image)
    if not stale:return {"drift":False,"stale_instances":[],"action":"no instance image drift detected"}
    if upgrade_mode=="Manual":
        action="verify health and capacity, then upgrade stale instances in controlled batches; confirm each instance reports the model image before proceeding"
    elif upgrade_mode=="Rolling":action="inspect rolling upgrade health and pause/resume policy; do not start a parallel manual rollout"
    else:action="inspect automatic upgrade failures and instance health before retrying"
    return {"drift":True,"stale_instances":stale,"action":action}
